pragma solidity ^0.4.19;

contract MONEY_BOX
{
struct Holder
{
uint unlockTime;
uint balance;
}

mapping (address => Holder) public Acc;

uint public MinSum;

Log LogFile;

bool intitalized;

function SetMinSum(uint _val)
public
{
if(intitalized)throw;
MinSum = _val;
}

